import{_ as a,o as n,c as l,aw as o}from"./chunks/framework.DLufY-ao.js";const u=JSON.parse('{"title":"Программная навигация","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/frameworks/vue-router/variants/navigation.md","filePath":"wiki/dev-commit/frameworks/vue-router/variants/navigation.md"}'),p={name:"wiki/dev-commit/frameworks/vue-router/variants/navigation.md"};function e(t,s,r,c,i,y){return n(),l("div",null,[...s[0]||(s[0]=[o(`<h1 id="программная-навигация" tabindex="-1">Программная навигация <a class="header-anchor" href="#программная-навигация" aria-label="Permalink to &quot;Программная навигация&quot;">​</a></h1><ul><li><p>router.push(location, onComplete?, onAbort?) (аналог: window.history.pushState) - для перехода к новому URL. Метод добавляет новую запись в историю навигации, что позволяет клику пользователя по кнопке &quot;назад&quot; в браузере сработать привычным образом. В качестве аргумента можно передать строку или объект, описывающий маршрут</p></li><li><p>router.replace(location, onComplete?, onAbort?) (аналог: window.history.replaceState) - действует как router.push, с той лишь разницей, что переход осуществляется без добавления новой записи в историю навигации, а заменяет текущую запись в нём</p></li><li><p>router.go(n) (аналог: window.history.go) - метод принимает параметром целое число, которое указывает на сколько шагов необходимо перейти по истории навигации</p></li><li><p>Внутри экземпляра Vue у вас есть доступ к экземпляру маршрутизатора через $router. Поэтому можно вызвать this.$router.push</p></li></ul><h3 id="push" tabindex="-1">push <a class="header-anchor" href="#push" aria-label="Permalink to &quot;push&quot;">​</a></h3><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#383A42;">&lt;router-link :</span><span style="color:#E45649;">to</span><span style="color:#383A42;">=</span><span style="color:#50A14F;">&quot;...&quot;</span><span style="color:#383A42;">&gt;	</span><span style="color:#A0A1A7;font-style:italic;"># декларативная запись</span></span>
<span class="line"><span style="color:#4078F2;">router.push(...</span><span style="color:#383A42;">)        </span><span style="color:#A0A1A7;font-style:italic;"># программная запись</span></span></code></pre></div><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#A0A1A7;font-style:italic;">// строка</span></span>
<span class="line"><span style="color:#383A42;">router.</span><span style="color:#4078F2;">push</span><span style="color:#383A42;">(</span><span style="color:#50A14F;">&#39;home&#39;</span><span style="color:#383A42;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#A0A1A7;font-style:italic;">// объект</span></span>
<span class="line"><span style="color:#383A42;">router.</span><span style="color:#4078F2;">push</span><span style="color:#383A42;">({ </span><span style="color:#E45649;">path</span><span style="color:#0184BC;">:</span><span style="color:#50A14F;"> &#39;home&#39;</span><span style="color:#383A42;"> })</span></span>
<span class="line"></span>
<span class="line"><span style="color:#A0A1A7;font-style:italic;">// именованный маршрут</span></span>
<span class="line"><span style="color:#383A42;">router.</span><span style="color:#4078F2;">push</span><span style="color:#383A42;">({ </span><span style="color:#E45649;">name</span><span style="color:#0184BC;">:</span><span style="color:#50A14F;"> &#39;user&#39;</span><span style="color:#383A42;">, </span><span style="color:#E45649;">params</span><span style="color:#0184BC;">:</span><span style="color:#383A42;"> { </span><span style="color:#E45649;">userId</span><span style="color:#0184BC;">:</span><span style="color:#50A14F;"> &#39;123&#39;</span><span style="color:#383A42;"> } })</span></span>
<span class="line"></span>
<span class="line"><span style="color:#A0A1A7;font-style:italic;">// со строкой запроса, получится /register?plan=private</span></span>
<span class="line"><span style="color:#383A42;">router.</span><span style="color:#4078F2;">push</span><span style="color:#383A42;">({ </span><span style="color:#E45649;">path</span><span style="color:#0184BC;">:</span><span style="color:#50A14F;"> &#39;register&#39;</span><span style="color:#383A42;">, </span><span style="color:#E45649;">query</span><span style="color:#0184BC;">:</span><span style="color:#383A42;"> { </span><span style="color:#E45649;">plan</span><span style="color:#0184BC;">:</span><span style="color:#50A14F;"> &#39;private&#39;</span><span style="color:#383A42;"> } })</span></span></code></pre></div><h3 id="replace" tabindex="-1">replace <a class="header-anchor" href="#replace" aria-label="Permalink to &quot;replace&quot;">​</a></h3><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#383A42;">&lt;router-link :</span><span style="color:#E45649;">to</span><span style="color:#383A42;">=</span><span style="color:#50A14F;">&quot;...&quot;</span><span style="color:#4078F2;"> replace</span><span style="color:#383A42;">&gt; </span><span style="color:#A0A1A7;font-style:italic;"># декларативная запись</span></span>
<span class="line"><span style="color:#4078F2;">router.replace(...</span><span style="color:#383A42;">)             </span><span style="color:#A0A1A7;font-style:italic;"># программная запись</span></span></code></pre></div><h3 id="go" tabindex="-1">go <a class="header-anchor" href="#go" aria-label="Permalink to &quot;go&quot;">​</a></h3><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#A0A1A7;font-style:italic;">// перейти на одну запись вперёд, эквивалентно history.forward()</span></span>
<span class="line"><span style="color:#383A42;">router.</span><span style="color:#4078F2;">go</span><span style="color:#383A42;">(</span><span style="color:#986801;">1</span><span style="color:#383A42;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#A0A1A7;font-style:italic;">// перейти на одну запись назад, эквивалентно history.back()</span></span>
<span class="line"><span style="color:#383A42;">router.</span><span style="color:#4078F2;">go</span><span style="color:#383A42;">(</span><span style="color:#0184BC;">-</span><span style="color:#986801;">1</span><span style="color:#383A42;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#A0A1A7;font-style:italic;">// перейти на 3 записи вперёд</span></span>
<span class="line"><span style="color:#383A42;">router.</span><span style="color:#4078F2;">go</span><span style="color:#383A42;">(</span><span style="color:#986801;">3</span><span style="color:#383A42;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#A0A1A7;font-style:italic;">// если записей в истории недостаточно много, переход просто не произойдёт</span></span>
<span class="line"><span style="color:#383A42;">router.</span><span style="color:#4078F2;">go</span><span style="color:#383A42;">(</span><span style="color:#0184BC;">-</span><span style="color:#986801;">100</span><span style="color:#383A42;">)</span></span>
<span class="line"><span style="color:#383A42;">router.</span><span style="color:#4078F2;">go</span><span style="color:#383A42;">(</span><span style="color:#986801;">100</span><span style="color:#383A42;">)</span></span></code></pre></div>`,9)])])}const d=a(p,[["render",e]]);export{u as __pageData,d as default};
